import{_ as a,C as i,o as r,c as s,E as n,a2 as o}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"A Smaller Skill Is Not the Same Skill","description":"","frontmatter":{"title":"A Smaller Skill Is Not the Same Skill","date":"2026-09-02","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"压缩或动态改写后的技能包要继续沿用原能力身份，必须保持哪些不变量？","summary":"SkillZip Pro reports meaningful token reductions under protected compression and a sharp loss under an aggressive configuration. The engineering lesson is not simply to compress less: progressively loaded skills need version-bound evidence for public entries, routes, resource boundaries and behavior.","sources":["research/analysis/Q-20260902-03-skill-compression-routing-contract.md"],"item_id":"Q-20260902-03","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-02-a-smaller-skill-is-not-the-same-skill-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md","filePath":"en/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md","lastUpdated":1788361073000}'),l={name:"en/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill.md"};function d(c,e,u,p,h,m){const t=i("ArticleCover");return r(),s("div",null,[n(t,{image:"/assets/covers/daily-2026-09-02-a-smaller-skill-is-not-the-same-skill-cover.png",kicker:"Open-source Engineering · Daily Research",title:"A Smaller Skill Is Not the Same Skill",summary:"SkillZip Pro reports meaningful token reductions under protected compression and a sharp loss under an aggressive configuration. The engineering lesson is not simply to compress less: progressively loaded skills need version-bound evidence for public entries, routes, resource boundaries and behavior.",version:"Q-20260902-03",status:"Daily Runtime V5 · 2026-09-02",languageHref:"/zh/engineering/2026-09-02-a-smaller-skill-is-not-the-same-skill",languageLabel:"中文"}),e[0]||(e[0]=o('<h1 id="a-smaller-skill-is-not-the-same-skill" tabindex="-1">A Smaller Skill Is Not the Same Skill <a class="header-anchor" href="#a-smaller-skill-is-not-the-same-skill" aria-label="Permalink to &quot;A Smaller Skill Is Not the Same Skill&quot;">​</a></h1><p>A compression pass removes repeated instructions and trims references. Every file still appears in the package, the root entry still loads, and the token count drops. Yet one public subskill can no longer be called directly, while a conditional resource now loads through the wrong route. The bundle is smaller, but is it still the same capability?</p><p>For a progressively loaded skill, file presence is not enough. The package behaves like a routed graph: root instructions select references, schemas, scripts, assets, and nested subskills only when an execution path needs them. Compression can preserve the visible directory while changing the routes that make it executable.</p><p>The primary study <em>SkillZip Pro</em> reports encouraging results for protected compression and a warning for aggressive optimization. In its evaluated content-moderation harness, the protected method removes about 38% of bundle tokens and reduces end-to-end per-run tokens by 10.4%, with no reported quality loss. On an evaluated multi-entry bundle it reports near-perfect route and public-entry preservation. An unprotected 71% configuration, however, loses as much as 26 accuracy points through one-sided false positives.</p><p>These are author-reported results, not independent validation. Their bounded engineering lesson is still clear: <strong>a compressed skill should retain the old capability identity only after its structural and behavioral contracts are re-established for the emitted version.</strong></p><h2 id="a-skill-bundle-is-a-routed-graph" tabindex="-1">A Skill Bundle Is a Routed Graph <a class="header-anchor" href="#a-skill-bundle-is-a-routed-graph" aria-label="Permalink to &quot;A Skill Bundle Is a Routed Graph&quot;">​</a></h2><p>Flat-prompt optimization asks whether roughly the same instructions remain. Progressive loading asks stronger questions. Can every public entry still be invoked independently? Does each required route resolve to the intended resource? Do private, public, and conditional classifications still hold? Do deduplication assumptions match the target runtime?</p><p>A root skill can pass a smoke test while a public subskill fails. A reference can remain in the tree but become unreachable under the conditions that previously selected it. A script can be reached through a new route while receiving different inputs or permissions. Those are contract changes even when a file comparison looks benign.</p><p>The skill&#39;s identity therefore includes more than prose. It includes callable entries, routing rules, visibility boundaries, environment assumptions, and the version/provenance chain connecting the source bundle to the candidate.</p><h2 id="the-numbers-support-a-bounded-claim" tabindex="-1">The Numbers Support a Bounded Claim <a class="header-anchor" href="#the-numbers-support-a-bounded-claim" aria-label="Permalink to &quot;The Numbers Support a Bounded Claim&quot;">​</a></h2><p>The protected results show that meaningful compression and route preservation can coexist in the reported setup. They do not establish a universal safe ratio. About 38% bundle-token reduction and 10.4% per-run reduction describe one evaluated system and harness, not a threshold that every package can adopt.</p><p>The aggressive case matters because the damage is asymmetric. A 71% configuration does not merely degrade an average score; the paper reports losses of up to 26 accuracy points through one-sided false positives. An availability check or token metric would miss that failure distribution.</p><p>Compression ratio is therefore an optimization metric, not an admission criterion. The relevant question is which contract surfaces were preserved and what evidence supports that claim in this bundle version.</p><h2 id="structural-preservation-needs-explicit-evidence" tabindex="-1">Structural Preservation Needs Explicit Evidence <a class="header-anchor" href="#structural-preservation-needs-explicit-evidence" aria-label="Permalink to &quot;Structural Preservation Needs Explicit Evidence&quot;">​</a></h2><p>A minimum structural contract covers public callable entries, internal route reachability, resource visibility, environment assumptions, and provenance.</p><p>Public entries need stable identities and standalone reachability. Required internal paths must resolve to intended resources. Private, public, and conditional material must retain its access and loading boundaries. Removed duplication must truly be supplied by the target environment. The emitted candidate must record its source hash, transformation, candidate hash, audit results, and adoption decision.</p><p>Binding evidence to the emitted version is essential. A later Zip-on-Write mutation cannot inherit a previous audit simply because it has the same directory name or descends from the same source. The change produces a new candidate and a new evidence boundary.</p><h2 id="routing-is-necessary-but-not-sufficient" tabindex="-1">Routing Is Necessary but Not Sufficient <a class="header-anchor" href="#routing-is-necessary-but-not-sufficient" aria-label="Permalink to &quot;Routing Is Necessary but Not Sufficient&quot;">​</a></h2><p>A perfect route audit proves that nodes remain reachable. It does not prove that a reached script has the same semantics, that permission requirements are unchanged, or that external effects remain safe.</p><p>Static routing checks and task-level evaluation answer different questions. Structural audits can confirm entries and paths. Behavioral tests can sample outputs, error distributions, and environmental compatibility. Permission and side-effect checks must verify the authority and effect contracts that a skill claims to preserve.</p><p>This is why “evaluation-free compression” should not be read as “validation-free adoption.” A compressor may avoid running a full benchmark on every internal edit while the governance process still requires bounded evidence before making a new bundle active.</p><h2 id="adopt-candidates-do-not-rewrite-identity-in-place" tabindex="-1">Adopt Candidates, Do Not Rewrite Identity in Place <a class="header-anchor" href="#adopt-candidates-do-not-rewrite-identity-in-place" aria-label="Permalink to &quot;Adopt Candidates, Do Not Rewrite Identity in Place&quot;">​</a></h2><p>A safer lifecycle treats optimization output as staged candidate material. The system records the immutable source version and transform, audits public entries and routes, runs risk-matched behavioral checks, and then makes an explicit adoption decision.</p><p>Rollback targets a prior adopted bundle identity, not a reconstructed approximation. If post-adoption evidence reveals a missed route, asymmetric error, permission drift, or environmental mismatch, the runtime can restore the exact previous artifact and retain the failed candidate for analysis.</p><p>Validation depth should match the claim. A documentation-only resource may need structural and rendering checks. A skill that can write data or call external tools needs permission, error, and effect-boundary evidence as well. Token savings never widen what the evidence can authorize.</p><h2 id="the-evidence-boundary-remains-narrow" tabindex="-1">The Evidence Boundary Remains Narrow <a class="header-anchor" href="#the-evidence-boundary-remains-narrow" aria-label="Permalink to &quot;The Evidence Boundary Remains Narrow&quot;">​</a></h2><p>The paper reports selected bundles and a specific industrial multi-round harness. It does not independently establish complete semantic equivalence, authorization preservation, external-effect safety, immutable provenance, or exactly-once behavior for arbitrary skills and plugins.</p><p>Its defensible result is narrower: protected compression can retain important routing surfaces while reducing tokens in the evaluated setup, and aggressive unprotected compression can cause large asymmetric failure. That makes version-bound contract preservation a first-class optimization requirement.</p><p>Open questions remain: which route and entry invariants can be verified statically; how much behavioral sampling follows a route-preserving transform; how permissions and side effects should be expressed alongside loading routes; and which evidence should trigger automatic rollback?</p><p><strong>Primary source:</strong> <a href="https://arxiv.org/abs/2608.30785" target="_blank" rel="noreferrer">SkillZip Pro: Execution-Aware Dynamic Compression of Progressively Loaded Skills for Self-Evolving Agents</a></p>',30))])}const g=a(l,[["render",d]]);export{b as __pageData,g as default};
